const assert = require('assert');
const fs = require('fs');
const tty = require('tty');
const { Socket } = require('net');

module.exports = function () {
  const native = globalThis.__tov_native;
  const mode = process.env.TOV_TTY_TEST;
  if (mode === 'probe') {
    console.log(process.stdin.isTTY);
    return;
  }
  if (mode === 'master-eof') {
    const input = new tty.ReadStream(Number(process.env.TOV_TTY_MASTER));
    input.setRawMode(true);
    input.on('data', () => {});
    input.on('end', () => {
      input.destroy();
      console.log('EOF');
    });
    console.log('READY');
    return;
  }
  if (mode.startsWith('signal-')) {
    const input = process.stdin;
    const prior = () => assert.fail('removed prior listener called');
    if (mode === 'signal-prior') process.on('SIGTERM', prior);
    if (mode !== 'signal-plain') input.setRawMode(true);
    if (mode === 'signal-prior') process.removeListener('SIGTERM', prior);
    if (mode === 'signal-cleared') input.setRawMode(false);
    if (['signal-busy', 'signal-cleared', 'signal-plain'].includes(mode)) {
      fs.writeSync(1, 'READY\n');
      // Deliberately keep JS busy: default termination must not await the loop.
      for (let i = 0; i < 1e12; i++) {}
      assert.fail('expected external termination');
    }
    if (mode === 'signal-listener') {
      process.on('SIGTERM', () => {
        assert.strictEqual(input.isRaw, true);
        console.log('LISTENER');
      });
      input.on('data', () => {
        input.setRawMode(false);
        input.destroy();
        console.log('DONE');
      });
    } else {
      if (mode === 'signal-removed') {
        const listener = () => assert.fail('removed listener called');
        process.on('SIGTERM', listener);
        process.removeListener('SIGTERM', listener);
      }
      input.on('data', () => {});
    }
    console.log('READY');
    return;
  }
  if (mode === 'stdio') {
    assert(process.stdin instanceof tty.ReadStream);
    assert.strictEqual(process.stdout.isTTY, true);
    assert.strictEqual(process.stderr.isTTY, true);
    assert.deepStrictEqual(process.stdout.getWindowSize(), [80, 24]);
    console.log('stdout ok');
    process.stderr.write('stderr ok\n');
    process.stdin.destroy();
    return;
  }
  if (mode === 'plain') {
    assert.strictEqual(native.guessHandleType(0), 'FILE');
    assert.strictEqual(process.stdin.isTTY, undefined);
    let text = '';
    process.stdin.on('data', (data) => { text += data.toString(); });
    process.stdin.on('end', () => {
      assert.strictEqual(text, process.env.TOV_TTY_EXPECTED);
      console.log('plain ok');
    });
    return;
  }
  if (mode === 'types') {
    for (const kind of ['PIPE', 'TCP', 'UDP']) {
      assert.strictEqual(native.guessHandleType(Number(process.env[`TOV_FD_${kind}`])), kind);
    }
    const file = fs.openSync(__filename, 'r');
    const devnull = fs.openSync('/dev/null', 'r');
    assert.strictEqual(native.guessHandleType(file), 'FILE');
    assert.strictEqual(native.guessHandleType(devnull), 'FILE');
    assert.strictEqual(native.guessHandleType(0), 'PIPE');
    assert.strictEqual(native.guessHandleType(-1), 'UNKNOWN');
    // Exercise the binding's consumer, not only the native classifier.
    const input = new Socket({ fd: 0, readable: true, writable: false });
    input.on('data', (data) => {
      assert.strictEqual(data.toString(), 'pipe keys');
      input.destroy();
      console.log('types ok');
    });
    fs.closeSync(file);
    fs.closeSync(devnull);
    return;
  }
  const fd = mode === 'fd' ? Number(process.env.TOV_TTY_FD) : 0;
  const input = mode === 'fd' ? new tty.ReadStream(fd) : process.stdin;
  assert(input instanceof tty.ReadStream);
  assert.strictEqual(native.guessHandleType(fd), 'TTY');
  assert.strictEqual(input.isTTY, true);
  const size = [];
  assert.strictEqual(input._handle.getWindowSize(size), 0);
  assert.deepStrictEqual(size, [80, 24]);
  assert.strictEqual(input.isRaw, false);
  assert.strictEqual(input.setRawMode(true), input);
  assert.strictEqual(input.isRaw, true);
  assert.strictEqual(input.setRawMode(false), input);
  assert.strictEqual(input.isRaw, false);
  input.setRawMode(true);
  const masterOwner = new tty.ReadStream(Number(process.env.TOV_TTY_MASTER), { manualStart: true });
  masterOwner.setRawMode(true);
  const other = new tty.ReadStream(Number(process.env.TOV_TTY_OTHER), { manualStart: true });
  other.setRawMode(true);
  // Two handles of one terminal must not restore each other's raw snapshot.
  const sibling = new tty.ReadStream(fs.openSync(process.env.TOV_TTY_PATH, 'r+'), { manualStart: true });
  sibling.setRawMode(true);
  input.setRawMode(false);
  masterOwner.setRawMode(false);
  assert.strictEqual(input._handle.writeUtf8String({ oncomplete: (status) => assert.strictEqual(status, 0) }, 'output'), mode === 'readonly' ? -9 : 0);
  let text = '';
  input.on('data', (data) => {
    text += data.toString();
    if (text.length < 4) return;
    assert.strictEqual(text, 'keys');
    if (mode !== 'exit') sibling.setRawMode(false);
    if (mode !== 'exit') {
      sibling.destroy();
      masterOwner.destroy();
      other.destroy();
      input.destroy();
    }
    console.log('read ok');
    if (mode === 'exit') process.exit(0);
  });
  console.log('READY');
};
